Running command: cat > /workspace/test_brotli4.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <brotli/decode.h>

int main() {
    FILE* f = fopen("/workspace/poc.bin", "rb");
    fseek(f, 32, SEEK_SET);
    unsigned char buf[32768];
    size_t n = fread(buf, 1, 32768, f);
    fclose(f);

    BrotliDecoderState* state = BrotliDecoderCreateInstance(NULL, NULL, NULL);
    size_t available_in = n;
    const uint8_t* next_in = buf;
    size_t total_out = 0;
    unsigned char* arr = malloc(131072);

    // First, decompress 131071 bytes (fill buffer to 131071)
    size_t available_out = 131071;
    uint8_t* next_out = arr;
    BrotliDecoderResult result = BrotliDecoderDecompressStream(state, &available_in, &next_in, &available_out, &next_out, &total_out);
    printf("after first: total_out=%zu avail_out=%zu result=%d\n", total_out, available_out, result);

    // Now call with avail_out=1 (small)
    available_out = 1;
    next_out = arr + total_out;
    result = BrotliDecoderDecompressStream(state, &available_in, &next_in, &available_out, &next_out, &total_out);
    printf("after second: total_out=%zu avail_out=%zu result=%d\n", total_out, available_out, result);

    BrotliDecoderDestroyInstance(state);
    free(arr);
    return 0;
}
EOF
gcc -o /workspace/test_brotli4 /workspace/test_brotli4.c -lbrotlidec && /workspace/test_brotli4

